window.OLP=[{"id":"p1","name":"Tổng đoạn con liên tiếp lớn nhất (Maximum Subarray Sum)","category":"Dynamic Programming","difficulty":"Cơ bản","description":"Cho một dãy số nguyên a gồm n phần tử. Hãy tìm một đoạn con liên tiếp gồm ít nhất một phần tử sao cho tổng các phần tử trong đoạn con này là lớn nhất.","inputFormat":"Dòng đầu tiên chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (-10^9 <= ai <= 10^9).","outputFormat":"In ra một số nguyên duy nhất là tổng lớn nhất của đoạn con liên tiếp.","constraints":["Subtask 1 (30%): n <= 1000","Subtask 2 (70%): n <= 200,000, -10^9 <= ai <= 10^9"],"samples":[{"input":"8\n-1 3 -2 5 3 -5 2 2","output":"9","explanation":"Đoạn con liên tiếp [3, -2, 5, 3] có tổng là 3 + (-2) + 5 + 3 = 9 là lớn nhất."},{"input":"5\n-5 -2 -8 -1 -4","output":"-1","explanation":"Đoạn con chỉ gồm 1 phần tử [-1] cho tổng lớn nhất là -1."}],"testCases":[{"input":"8\n-1 3 -2 5 3 -5 2 2","expected":"9"},{"input":"5\n-5 -2 -8 -1 -4","expected":"-1"},{"input":"1\n100","expected":"100"},{"input":"6\n1 2 3 4 5 6","expected":"21"},{"input":"7\n-2 1 -3 4 -1 2 1","expected":"6"}]},{"id":"p2","name":"Tổng hai số trên mảng sắp xếp (Two Sum on Sorted Array)","category":"Two Pointers","difficulty":"Cơ bản","description":"Cho dãy n số nguyên đã được sắp xếp tăng dần và một số nguyên đích X. Hãy tìm 2 vị trí khác nhau i < j (chỉ số 1-based) sao cho a[i] + a[j] = X. Nếu có nhiều cặp, in ra cặp đầu tiên tìm được. Nếu không có cặp nào, in ra -1.","inputFormat":"Dòng đầu chứa 2 số nguyên n và X (2 <= n <= 200,000; 1 <= X <= 2.10^9).\\nDòng thứ hai chứa n số nguyên a1 <= a2 <= ... <= an (1 <= ai <= 10^9).","outputFormat":"In ra 2 số nguyên i và j (1 <= i < j <= n) phân tách nhau bởi dấu cách, hoặc -1 nếu không tồn tại.","constraints":["Subtask 1 (40%): n <= 2000","Subtask 2 (60%): n <= 200,000"],"samples":[{"input":"5 12\n1 3 5 7 11","output":"1 5","explanation":"a[1] + a[5] = 1 + 11 = 12."}],"testCases":[{"input":"5 12\n1 3 5 7 11","expected":"1 5"},{"input":"4 7\n1 2 4 8","expected":"-1"},{"input":"6 10\n1 2 3 7 8 9","expected":"1 6"},{"input":"3 6\n2 3 4","expected":"1 3"},{"input":"4 10\n2 5 5 8","expected":"2 3"}]},{"id":"p3","name":"Truy vấn tổng đoạn con (Static Range Sum Queries)","category":"Prefix Sum","difficulty":"Cơ bản","description":"Cho mảng a gồm n số nguyên. Có q truy vấn, mỗi truy vấn gồm 2 số u, v (1-based), hãy in ra tổng các phần tử từ chỉ số u đến chỉ số v.","inputFormat":"Dòng đầu chứa 2 số nguyên n và q (1 <= n, q <= 200,000).\\nDòng hai chứa n số nguyên a1, ..., an.\\nq dòng tiếp theo mỗi dòng chứa 2 số nguyên u v.","outputFormat":"In ra kết quả của từng truy vấn trên một dòng.","constraints":["1 <= n, q <= 200,000","1 <= ai <= 10^9"],"samples":[{"input":"5 3\n3 2 4 5 1\n1 3\n2 4\n1 5","output":"9\n11\n15","explanation":"sum(1..3) = 3+2+4=9; sum(2..4) = 2+4+5=11; sum(1..5) = 15."}],"testCases":[{"input":"5 3\n3 2 4 5 1\n1 3\n2 4\n1 5","expected":"9\n11\n15"},{"input":"3 2\n10 20 30\n1 1\n2 3","expected":"10\n50"}]},{"id":"p4","name":"Khớp xâu ký tự (String Matching)","category":"String Algorithms","difficulty":"Trung bình","description":"Cho xâu văn bản s và xâu mẫu p. Hãy đếm số lần xâu mẫu p xuất hiện trong s.","inputFormat":"Dòng đầu chứa xâu s (1 <= |s| <= 10^6).\\nDòng hai chứa xâu p (1 <= |p| <= 10^6).","outputFormat":"In ra một số nguyên là số lần xuất hiện.","constraints":["Độ dài s, p <= 1,000,000; chỉ gồm các chữ cái tiếng Anh in thường a-z."],"samples":[{"input":"saippuakauppias\np","output":"3","explanation":"Ký tự p xuất hiện 3 lần."},{"input":"aaaaa\naa","output":"4","explanation":"Mẫu aa xuất hiện tại các vị trí 0, 1, 2, 3."}],"testCases":[{"input":"saippuakauppias\np","expected":"3"},{"input":"aaaaa\naa","expected":"4"},{"input":"abcdef\ngh","expected":"0"}]},{"id":"p5","name":"Đường đi ngắn nhất nguồn đơn (Shortest Routes I)","category":"Graph","difficulty":"Nâng cao","description":"Có n thành phố và m chuyến bay một chiều. Hãy tính khoảng cách ngắn nhất từ thành phố 1 tới tất cả các thành phố từ 1 đến n.","inputFormat":"Dòng đầu chứa 2 số nguyên n và m (1 <= n, m <= 100,000).\\nm dòng tiếp theo mỗi dòng chứa a b c biểu thị chuyến bay từ a đến b có độ dài c.","outputFormat":"In ra n số nguyên: khoảng cách ngắn nhất từ 1 đến các thành phố 1, 2, ..., n.","constraints":["1 <= n, m <= 100,000","1 <= c <= 10^9"],"samples":[{"input":"3 4\n1 2 6\n1 3 2\n3 2 3\n1 3 4","output":"0 5 2","explanation":"Đến 1: 0; Đến 2: 1 -> 3 -> 2 (2 + 3 = 5); Đến 3: 2."}],"testCases":[{"input":"3 4\n1 2 6\n1 3 2\n3 2 3\n1 3 4","expected":"0 5 2"}]},{"id":"p6","name":"Bài toán Cái túi 0/1 (0-1 Knapsack)","category":"Dynamic Programming","difficulty":"Trung bình","description":"Có n đồ vật, đồ vật thứ i có khối lượng w[i] và giá trị v[i]. Cái túi có tải trọng tối đa là W. Hãy chọn một tập hợp các đồ vật sao cho tổng khối lượng không vượt quá W và tổng giá trị thu được là lớn nhất.","inputFormat":"Dòng đầu chứa 2 số nguyên n và W (1 <= n <= 1000; 1 <= W <= 100,000).\\nn dòng tiếp theo, dòng thứ i chứa 2 số nguyên w[i] và v[i] (1 <= w[i], v[i] <= 10^5).","outputFormat":"In ra một số nguyên duy nhất là giá trị lớn nhất có thể thu được.","constraints":["n <= 1000","W <= 100,000"],"samples":[{"input":"4 7\n1 1\n3 4\n4 5\n5 7","output":"9","explanation":"Chọn đồ vật 2 (w=3, v=4) và đồ vật 3 (w=4, v=5). Tổng khối lượng = 7, tổng giá trị = 9."}],"testCases":[{"input":"4 7\n1 1\n3 4\n4 5\n5 7","expected":"9"},{"input":"3 5\n2 3\n3 4\n4 5","expected":"7"},{"input":"1 10\n15 20","expected":"0"}]},{"id":"p7","name":"Dãy con tăng dài nhất (Longest Increasing Subsequence)","category":"Dynamic Programming","difficulty":"Trung bình","description":"Cho mảng a gồm n số nguyên. Hãy tìm độ dài của dãy con tăng nghiêm ngặt dài nhất (không nhất thiết phải liên tiếp).","inputFormat":"Dòng đầu chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (1 <= ai <= 10^9).","outputFormat":"In ra độ dài của dãy con tăng dài nhất.","constraints":["n <= 200,000","1 <= ai <= 10^9"],"samples":[{"input":"8\n7 3 5 3 6 2 9 8","output":"4","explanation":"Dãy con tăng dài nhất là [3, 5, 6, 8] hoặc [3, 5, 6, 9], độ dài bằng 4."}],"testCases":[{"input":"8\n7 3 5 3 6 2 9 8","expected":"4"},{"input":"5\n5 4 3 2 1","expected":"1"},{"input":"6\n1 2 3 4 5 6","expected":"6"}]},{"id":"p8","name":"Đếm số nguyên tố nhỏ hơn hoặc bằng N","category":"Number Theory","difficulty":"Cơ bản","description":"Cho số nguyên dương N. Hãy đếm có bao nhiêu số nguyên tố nằm trong đoạn từ 1 đến N.","inputFormat":"Một số nguyên duy nhất N (1 <= N <= 5,000,000).","outputFormat":"In ra số lượng số nguyên tố.","constraints":["1 <= N <= 5,000,000"],"samples":[{"input":"10","output":"4","explanation":"Có 4 số nguyên tố: 2, 3, 5, 7."},{"input":"20","output":"8","explanation":"2, 3, 5, 7, 11, 13, 17, 19."}],"testCases":[{"input":"10","expected":"4"},{"input":"20","expected":"8"},{"input":"1","expected":"0"},{"input":"100","expected":"25"}]},{"id":"p9","name":"Kiểm tra dãy ngoặc đúng (Valid Parentheses)","category":"Data Structures","difficulty":"Cơ bản","description":"Cho một chuỗi chỉ chứa các ký tự ngoặc: (,), [,], {,}. Hãy kiểm tra xem dãy ngoặc có hợp lệ hay không. In ra \"YES\" nếu hợp lệ, ngược lại in ra \"NO\".","inputFormat":"Một dòng duy nhất chứa chuỗi S (1 <= |S| <= 10^5).","outputFormat":"In ra \"YES\" hoặc \"NO\".","constraints":["|S| <= 100,000"],"samples":[{"input":"{[()]}","output":"YES","explanation":"Các ngoặc mở đóng đúng thứ tự."},{"input":"([)]","output":"NO","explanation":"Ngoặc lồng nhau không hợp lệ."}],"testCases":[{"input":"{[()]}","expected":"YES"},{"input":"([)]","expected":"NO"},{"input":"()()[]{}","expected":"YES"},{"input":"(((","expected":"NO"}]},{"id":"p10","name":"Ước chung lớn nhất & Bội chung nhỏ nhất (GCD and LCM)","category":"Number Theory","difficulty":"Cơ bản","description":"Cho hai số nguyên dương a và b. Hãy tìm ước chung lớn nhất (GCD) và bội chung nhỏ nhất (LCM) của chúng.","inputFormat":"Một dòng chứa 2 số nguyên a và b (1 <= a, b <= 10^9).","outputFormat":"In ra hai số nguyên phân tách bởi dấu cách: GCD và LCM.","constraints":["1 <= a, b <= 10^9"],"samples":[{"input":"12 18","output":"6 36","explanation":"GCD(12, 18) = 6; LCM(12, 18) = 36."}],"testCases":[{"input":"12 18","expected":"6 36"},{"input":"7 13","expected":"1 91"},{"input":"100 25","expected":"25 100"}]},{"id":"p11","name":"Lũy thừa nhị phân Modulo (Binary Exponentiation)","category":"Number Theory","difficulty":"Cơ bản","description":"Tính a^b mod (10^9 + 7). Với 0 <= a, b <= 10^9. Quy ước 0^0 = 1.","inputFormat":"Hai số nguyên a và b.","outputFormat":"In ra kết quả a^b mod (10^9 + 7).","constraints":["0 <= a, b <= 10^9"],"samples":[{"input":"3 4","output":"81","explanation":"3^4 = 81."},{"input":"2 10","output":"1024","explanation":"2^10 = 1024."}],"testCases":[{"input":"3 4","expected":"81"},{"input":"2 10","expected":"1024"},{"input":"5 0","expected":"1"}]},{"id":"p12","name":"Đếm số thành phần liên thông đồ thị (Connected Components)","category":"Graph","difficulty":"Trung bình","description":"Cho đồ thị vô hướng gồm n đỉnh và m cạnh. Hãy đếm số lượng thành phần liên thông của đồ thị.","inputFormat":"Dòng đầu chứa 2 số nguyên n và m (1 <= n <= 100,000; 0 <= m <= 200,000).\\nm dòng tiếp theo mỗi dòng chứa u v biểu thị cạnh nối u và v.","outputFormat":"In ra số lượng thành phần liên thông.","constraints":["1 <= n <= 100,000","0 <= m <= 200,000"],"samples":[{"input":"5 3\n1 2\n2 3\n4 5","output":"2","explanation":"Có 2 thành phần liên thông: {1, 2, 3} và {4, 5}."}],"testCases":[{"input":"5 3\n1 2\n2 3\n4 5","expected":"2"},{"input":"4 0","expected":"4"},{"input":"3 3\n1 2\n2 3\n1 3","expected":"1"}]},{"id":"p13","name":"Sắp xếp dãy số (Sort an Array)","category":"Sorting & Searching","difficulty":"Cơ bản","description":"Cho mảng gồm n số nguyên. Hãy sắp xếp mảng theo thứ tự tăng dần.","inputFormat":"Dòng đầu chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên.","outputFormat":"In ra dãy số đã sắp xếp tăng dần, phân tách nhau bởi dấu cách.","constraints":["n <= 200,000","-10^9 <= ai <= 10^9"],"samples":[{"input":"5\n5 2 3 1 4","output":"1 2 3 4 5","explanation":"Dãy đã sắp xếp tăng dần."}],"testCases":[{"input":"5\n5 2 3 1 4","expected":"1 2 3 4 5"},{"input":"3\n-5 10 -2","expected":"-5 -2 10"}]},{"id":"p14","name":"Tìm đường đi trong ma trận mê cung (Grid BFS)","category":"Graph","difficulty":"Trung bình","description":"Cho ma trận mê cung kích thước N x M gồm các ô trống (0) và chướng ngại vật (1). Hãy tìm độ dài đường đi ngắn nhất từ ô xuất phát (1, 1) tới ô đích (N, M). Nếu không có đường đi, in ra -1.","inputFormat":"Dòng đầu chứa 2 số nguyên N và M (1 <= N, M <= 1000).\\nN dòng tiếp theo mỗi dòng chứa M số 0 hoặc 1.","outputFormat":"In ra độ dài đường đi ngắn nhất (tính theo số bước đi), hoặc -1.","constraints":["N, M <= 1000"],"samples":[{"input":"3 3\n0 0 0\n1 1 0\n0 0 0","output":"4","explanation":"(1,1) -> (1,2) -> (1,3) -> (2,3) -> (3,3): 4 bước."}],"testCases":[{"input":"3 3\n0 0 0\n1 1 0\n0 0 0","expected":"4"},{"input":"2 2\n0 1\n1 0","expected":"-1"},{"input":"1 1\n0","expected":"0"}]},{"id":"p15","name":"Lũy thừa nhị phân & Modulo (Binary Exponentiation)","category":"Math & Number Theory","difficulty":"Cơ bản","description":"Tính (a^b) mod m với các số nguyên dương a, b, m. Thuật toán lũy thừa nhị phân cho phép tính trong thời gian O(log b), rất quan trọng trong lý thuyết số và các bài toán tổ hợp modulo.","inputFormat":"Gồm 1 dòng duy nhất chứa 3 số nguyên dương a, b, m (1 <= a, b <= 10^18, 2 <= m <= 10^9 + 7).","outputFormat":"In ra kết quả (a^b) mod m.","constraints":["Subtask 1 (40%): b <= 10^6","Subtask 2 (60%): b <= 10^18"],"samples":[{"input":"2 10 1000","output":"24","explanation":"2^10 = 1024, 1024 mod 1000 = 24."},{"input":"3 18181818 1000000007","output":"573177696"}],"testCases":[{"input":"2 10 1000","expected":"24"},{"input":"3 5 100","expected":"43"},{"input":"5 0 1000000007","expected":"1"},{"input":"7 13 1000000007","expected":"694847539"}]},{"id":"p16","name":"Chặt cây lấy gỗ (EKO - Binary Search on Answer)","category":"Binary Search","difficulty":"Trung bình","description":"Lâm tặc Mirko cần lấy ít nhất M mét gỗ. Có N cái cây với độ cao h1, h2, ..., hN. Máy cưa được đặt ở độ cao H. Tất cả các phần cây cao hơn H sẽ bị cưa đứt, phần còn lại giữ nguyên. Tìm độ cao H nguyên lớn nhất sao cho tổng lượng gỗ cưa được ít nhất là M mét.","inputFormat":"Dòng đầu chứa hai số nguyên N và M (1 <= N <= 10^6, 1 <= M <= 2.10^9).\\nDòng thứ hai chứa N số nguyên h1, h2, ..., hN (1 <= hi <= 10^9).","outputFormat":"In ra một số nguyên duy nhất là độ cao H tối đa cần tìm.","constraints":["N <= 10^6, M <= 2.10^9, hi <= 10^9"],"samples":[{"input":"4 7\n20 15 10 17","output":"15","explanation":"Đặt cưa ở độ cao 15: lấy được (20-15) + (17-15) = 5 + 2 = 7 mét gỗ."},{"input":"5 20\n4 42 40 26 46","output":"36"}],"testCases":[{"input":"4 7\n20 15 10 17","expected":"15"},{"input":"5 20\n4 42 40 26 46","expected":"36"},{"input":"3 5\n10 10 10","expected":"8"}]},{"id":"p17","name":"Cây khung nhỏ nhất (Kruskal Minimal Spanning Tree)","category":"Graph","difficulty":"Trung bình","description":"Cho một đồ thị vô hướng liên thông gồm N đỉnh và M cạnh có trọng số. Hãy tìm tổng trọng số của một cây khung nhỏ nhất (MST) chứa tất cả N đỉnh.","inputFormat":"Dòng đầu tiên chứa N và M (1 <= N <= 100,000; 1 <= M <= 200,000).\\nM dòng tiếp theo, mỗi dòng gồm ba số nguyên u, v, w mô tả cạnh nối u và v với trọng số w (1 <= u, v <= N, 1 <= w <= 10^9).","outputFormat":"In ra một số nguyên duy nhất là tổng trọng số của cây khung nhỏ nhất.","constraints":["N <= 100,000, M <= 200,000"],"samples":[{"input":"4 5\n1 2 1\n1 3 4\n2 3 2\n2 4 5\n3 4 3","output":"6","explanation":"Cây khung gồm các cạnh: (1,2: 1), (2,3: 2), (3,4: 3) có tổng trọng số 1+2+3 = 6."}],"testCases":[{"input":"4 5\n1 2 1\n1 3 4\n2 3 2\n2 4 5\n3 4 3","expected":"6"},{"input":"3 3\n1 2 5\n2 3 5\n1 3 2","expected":"7"}]},{"id":"p18","name":"Xâu con chung dài nhất (Longest Common Subsequence - LCS)","category":"Dynamic Programming","difficulty":"Trung bình","description":"Cho hai xâu ký tự S1 và S2 chỉ gồm các chữ cái tiếng Anh in thường. Hãy tìm độ dài xâu con chung dài nhất của hai xâu (các ký tự không nhất thiết phải liên tiếp).","inputFormat":"Gồm hai dòng, dòng 1 chứa xâu S1, dòng 2 chứa xâu S2 (1 <= |S1|, |S2| <= 3000).","outputFormat":"In ra một số nguyên duy nhất là độ dài của xâu con chung dài nhất.","constraints":["|S1|, |S2| <= 3000"],"samples":[{"input":"abcde\nace","output":"3","explanation":"Xâu con chung dài nhất là \"ace\" có độ dài 3."},{"input":"algorithm\naltitude","output":"4","explanation":"Xâu con chung dài nhất là \"alit\" hoặc \"alti\" có độ dài 4."}],"testCases":[{"input":"abcde\nace","expected":"3"},{"input":"algorithm\naltitude","expected":"4"},{"input":"vietnam\nvietnam","expected":"7"},{"input":"abc\ndef","expected":"0"}]},{"id":"p19","name":"Đoạn con có tổng bằng K (Subarray Sum Equals K)","category":"Hashing & Prefix Sum","difficulty":"Trung bình","description":"Cho một dãy số nguyên a gồm n phần tử và một số nguyên K. Đếm số lượng đoạn con liên tiếp có tổng các phần tử đúng bằng K.","inputFormat":"Dòng đầu chứa n và K (1 <= n <= 200,000; -10^9 <= K <= 10^9).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (-10^9 <= ai <= 10^9).","outputFormat":"In ra số lượng đoạn con liên tiếp có tổng bằng K.","constraints":["n <= 200,000"],"samples":[{"input":"5 3\n1 2 3 -3 3","output":"3","explanation":"Các đoạn con có tổng bằng 3 là: [1, 2], [3], [3, -3, 3]."}],"testCases":[{"input":"5 3\n1 2 3 -3 3","expected":"3"},{"input":"3 2\n1 1 1","expected":"2"},{"input":"4 0\n1 -1 1 -1","expected":"4"}]},{"id":"p20","name":"Đếm số cặp nghịch thế (Inversion Count)","category":"Data Structure & Sorting","difficulty":"Trung bình","description":"Cho một dãy số nguyên A gồm n phần tử. Một cặp chỉ số (i, j) được gọi là cặp nghịch thế nếu 1 <= i < j <= n và A[i] > A[j]. Hãy đếm tổng số cặp nghịch thế trong dãy.","inputFormat":"Dòng đầu tiên chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (1 <= ai <= 10^9).","outputFormat":"In ra một số nguyên duy nhất là số cặp nghịch thế.","constraints":["n <= 200,000"],"samples":[{"input":"5\n2 4 1 3 5","output":"3","explanation":"Các cặp nghịch thế là (2, 1), (4, 1), (4, 3)."},{"input":"5\n5 4 3 2 1","output":"10"}],"testCases":[{"input":"5\n2 4 1 3 5","expected":"3"},{"input":"5\n5 4 3 2 1","expected":"10"},{"input":"4\n1 2 3 4","expected":"0"}]},{"id":"p21","name":"Cửa sổ trượt giá trị lớn nhất (Sliding Window Maximum)","category":"Two Pointers","difficulty":"Nâng cao","description":"Cho một mảng số nguyên A gồm n phần tử và một số nguyên k (1 <= k <= n). Một cửa sổ có độ dài k trượt từ trái sang phải qua mảng. Tại mỗi vị trí cửa sổ, hãy tìm phần tử lớn nhất trong cửa sổ đó.","inputFormat":"Dòng đầu tiên chứa hai số nguyên n và k (1 <= k <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (-10^9 <= ai <= 10^9).","outputFormat":"In ra n - k + 1 số nguyên, số thứ i là giá trị lớn nhất của cửa sổ thứ i, cách nhau một khoảng trắng.","constraints":["1 <= k <= n <= 200,000"],"samples":[{"input":"8 3\n1 3 -1 -3 5 3 6 7","output":"3 3 5 5 6 7","explanation":"Cửa sổ [1, 3, -1] max = 3; [3, -1, -3] max = 3; [-1, -3, 5] max = 5; ..."}],"testCases":[{"input":"8 3\n1 3 -1 -3 5 3 6 7","expected":"3 3 5 5 6 7"},{"input":"4 2\n4 3 2 1","expected":"4 3 2"},{"input":"3 1\n10 20 30","expected":"10 20 30"}]},{"id":"p22","name":"Tổ hợp chập K Modulo 10^9+7 (nCr Modular Arithmetic)","category":"Math & Number Theory","difficulty":"Cơ bản","description":"Tính giá trị tổ hợp chập k của n: C(n, k) = n! / (k! * (n - k)!) modulo 10^9 + 7. Sử dụng nghịch đảo modulo theo định lý Fermat nhỏ: a^(p-1) = 1 (mod p) => a^(-1) = a^(p-2) (mod p).","inputFormat":"Gồm một dòng chứa hai số nguyên n và k (0 <= k <= n <= 1,000,000).","outputFormat":"In ra một số nguyên duy nhất là C(n, k) mod (10^9 + 7).","constraints":["0 <= k <= n <= 1,000,000"],"samples":[{"input":"5 2","output":"10","explanation":"C(5, 2) = 5! / (2! * 3!) = 10."},{"input":"10 4","output":"210"}],"testCases":[{"input":"5 2","expected":"10"},{"input":"10 4","expected":"210"},{"input":"100 0","expected":"1"},{"input":"100 100","expected":"1"}]},{"id":"p23","name":"Đoạn con tăng liên tiếp dài nhất (Longest Increasing Subsegment)","category":"Two Pointers","difficulty":"Cơ bản","description":"Cho một dãy số nguyên gồm n phần tử. Hãy tìm độ dài lớn nhất của một đoạn con gồm các phần tử liên tiếp mà trong đó mỗi phần tử đều lớn hơn nghiêm ngặt phần tử đứng liền trước nó.","inputFormat":"Dòng đầu tiên chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (1 <= ai <= 10^9).","outputFormat":"In ra độ dài lớn nhất của đoạn con tăng liên tiếp.","constraints":["1 <= n <= 200,000"],"samples":[{"input":"5\n1 7 2 11 15","output":"3","explanation":"Đoạn [2, 11, 15] có độ dài 3 là đoạn con tăng liên tiếp dài nhất."}],"testCases":[{"input":"5\n1 7 2 11 15","expected":"3"},{"input":"4\n4 3 2 1","expected":"1"},{"input":"6\n1 2 3 4 5 6","expected":"6"}]},{"id":"p24","name":"Đếm số lượng ước số của N (Divisor Count)","category":"Math & Number Theory","difficulty":"Cơ bản","description":"Cho một số nguyên dương N. Hãy đếm số lượng ước số nguyên dương của N. Nếu N = p1^e1 * p2^e2 * ... * pk^ek thì số lượng ước số d(N) = (e1 + 1)(e2 + 1)...(ek + 1).","inputFormat":"Gồm một dòng chứa số nguyên dương N (1 <= N <= 10^12).","outputFormat":"In ra một số nguyên duy nhất là số lượng ước số của N.","constraints":["1 <= N <= 10^12"],"samples":[{"input":"12","output":"6","explanation":"Các ước số của 12 là 1, 2, 3, 4, 6, 12 (tổng cộng 6 ước)."},{"input":"16","output":"5","explanation":"Các ước của 16 là 1, 2, 4, 8, 16."}],"testCases":[{"input":"12","expected":"6"},{"input":"16","expected":"5"},{"input":"1","expected":"1"},{"input":"97","expected":"2"},{"input":"100","expected":"9"}]},{"id":"p25","name":"Tổ tiên chung gần nhất trên cây (LCA - Binary Lifting)","category":"Tree Algorithms","difficulty":"Nâng cao","description":"Cho một cây gồm n đỉnh có gốc tại đỉnh 1 và q truy vấn. Mỗi truy vấn gồm hai đỉnh u và v, hãy tìm tổ tiên chung gần nhất (LCA) của u và v.","inputFormat":"Dòng đầu tiên chứa hai số nguyên n và q (1 <= n, q <= 200,000).\\nDòng thứ hai chứa n - 1 số nguyên p2, p3, ..., pn là cha trực tiếp của các đỉnh 2, 3, ..., n.\\nq dòng tiếp theo, mỗi dòng chứa hai số nguyên u và v.","outputFormat":"In ra kết quả của mỗi truy vấn trên một dòng.","constraints":["n, q <= 200,000"],"samples":[{"input":"5 3\n1 1 3 3\n4 5\n2 5\n1 4","output":"3\n1\n1","explanation":"Cây có các cạnh: 1-2, 1-3, 3-4, 3-5. LCA(4, 5) = 3; LCA(2, 5) = 1; LCA(1, 4) = 1."}],"testCases":[{"input":"5 3\n1 1 3 3\n4 5\n2 5\n1 4","expected":"3\n1\n1"},{"input":"3 1\n1 2\n1 3","expected":"1"}]},{"id":"p26","name":"Segment Tree cập nhật đoạn (Range Add Range Sum with Lazy)","category":"Segment Tree","difficulty":"Nâng cao","description":"Cho một dãy số gồm n phần tử ban đầu đều bằng 0 và q truy vấn thuộc một trong hai loại:\\n- 1 l r v: Cộng giá trị v vào mọi phần tử trong đoạn từ l đến r.\\n- 2 l r: Tính tổng các phần tử trong đoạn từ l đến r.","inputFormat":"Dòng đầu chứa n và q (1 <= n, q <= 200,000).\\nq dòng tiếp theo chứa truy vấn loại 1 hoặc loại 2 (1 <= l <= r <= n; -10^9 <= v <= 10^9).","outputFormat":"In ra kết quả của các truy vấn loại 2.","constraints":["n, q <= 200,000"],"samples":[{"input":"5 4\n1 1 3 2\n1 2 5 3\n2 2 4\n2 1 5","output":"13\n18","explanation":"Sau 2 thao tác cộng: mảng là [2, 5, 5, 3, 3]. Tổng đoạn [2..4] = 5+5+3 = 13. Tổng [1..5] = 2+5+5+3+3 = 18."}],"testCases":[{"input":"5 4\n1 1 3 2\n1 2 5 3\n2 2 4\n2 1 5","expected":"13\n18"},{"input":"3 2\n1 1 3 10\n2 1 2","expected":"20"}]},{"id":"p27","name":"Trò chơi bốc sỏi Nim (Game Theory - Nim Sum)","category":"Game Theory","difficulty":"Trung bình","description":"Trò chơi Nim kinh điển: Có n đống sỏi, đống thứ i có ai viên sỏi. Hai người chơi A và B luân phiên bốc sỏi, người đi trước là A. Mỗi lượt, một người chơi được chọn một đống bất kỳ còn sỏi và lấy đi một số lượng sỏi tùy ý (ít nhất 1 viên, nhiều nhất là toàn bộ đống đó). Người bốc viên sỏi cuối cùng sẽ thắng cuộc. Cho biết ai là người có chiến thuật thắng nếu cả hai đều chơi tối ưu.","inputFormat":"Dòng đầu tiên chứa số nguyên n (1 <= n <= 200,000).\\nDòng thứ hai chứa n số nguyên a1, a2, ..., an (1 <= ai <= 10^9).","outputFormat":"In ra \"FIRST\" nếu người đi trước luôn thắng, hoặc \"SECOND\" nếu người đi sau thắng.","constraints":["n <= 200,000, ai <= 10^9"],"samples":[{"input":"3\n1 2 3","output":"SECOND","explanation":"Nim-sum = 1 XOR 2 XOR 3 = 0. Trạng thái thua -> người đi sau (SECOND) thắng."},{"input":"3\n2 5 4","output":"FIRST","explanation":"Nim-sum = 2 XOR 5 XOR 4 = 3 != 0 -> người đi trước (FIRST) thắng."}],"testCases":[{"input":"3\n1 2 3","expected":"SECOND"},{"input":"3\n2 5 4","expected":"FIRST"},{"input":"2\n10 10","expected":"SECOND"},{"input":"1\n100","expected":"FIRST"}]},{"id":"p28","name":"Đếm số lượng cạnh cầu trong đồ thị (Bridge Counting - Tarjan)","category":"Graph","difficulty":"Nâng cao","description":"Cho một đồ thị vô hướng gồm n đỉnh và m cạnh. Một cạnh được gọi là cạnh cầu (bridge) nếu việc loại bỏ nó sẽ làm tăng số thành phần liên thông của đồ thị. Hãy đếm số lượng cạnh cầu trong đồ thị.","inputFormat":"Dòng đầu tiên chứa n và m (1 <= n <= 100,000; 1 <= m <= 200,000).\\nm dòng tiếp theo mỗi dòng chứa hai số u và v mô tả cạnh vô hướng nối u và v.","outputFormat":"In ra một số nguyên duy nhất là số lượng cạnh cầu.","constraints":["n <= 100,000, m <= 200,000"],"samples":[{"input":"5 5\n1 2\n2 3\n3 1\n3 4\n4 5","output":"2","explanation":"Hai cạnh cầu là (3, 4) và (4, 5)."}],"testCases":[{"input":"5 5\n1 2\n2 3\n3 1\n3 4\n4 5","expected":"2"},{"input":"3 3\n1 2\n2 3\n3 1","expected":"0"},{"input":"4 3\n1 2\n2 3\n3 4","expected":"3"}]},{"id":"p29","name":"Người du lịch TSP (Traveling Salesperson Problem - Bitmask DP)","category":"Dynamic Programming","difficulty":"Nâng cao","description":"Có N thành phố đánh số từ 0 đến N - 1 và ma trận chi phí cost[i][j] đi từ thành phố i sang thành phố j. Người du lịch xuất phát từ thành phố 0, phải ghé thăm tất cả các thành phố còn lại đúng một lần rồi quay trở lại thành phố 0. Hãy tìm tổng chi phí hành trình nhỏ nhất.","inputFormat":"Dòng đầu tiên chứa số nguyên N (2 <= N <= 16).\\nN dòng tiếp theo, mỗi dòng chứa N số nguyên là ma trận khoảng cách cost[i][j] (0 <= cost[i][j] <= 10,000; cost[i][i] = 0).","outputFormat":"In ra một số nguyên duy nhất là tổng chi phí nhỏ nhất.","constraints":["2 <= N <= 16"],"samples":[{"input":"4\n0 10 15 20\n10 0 35 25\n15 35 0 30\n20 25 30 0","output":"80","explanation":"Chu trình: 0 -> 1 -> 3 -> 2 -> 0 có chi phí 10 + 25 + 30 + 15 = 80."}],"testCases":[{"input":"4\n0 10 15 20\n10 0 35 25\n15 35 0 30\n20 25 30 0","expected":"80"},{"input":"3\n0 1 2\n1 0 1\n2 1 0","expected":"4"}]},{"id":"p30","name":"Luồng cực đại trên mạng (Maximum Flow - Edmonds-Karp)","category":"Graph","difficulty":"Nâng cao","description":"Cho một mạng luồng gồm n đỉnh đánh số từ 1 đến n và m cung có hướng, mỗi cung có một sức chứa c(u, v). Đỉnh 1 là điểm phát (source s) và đỉnh n là điểm thu (sink t). Hãy tìm giá trị luồng cực đại có thể chuyển từ đỉnh 1 tới đỉnh n.","inputFormat":"Dòng đầu tiên chứa hai số nguyên n và m (2 <= n <= 500, 1 <= m <= 1000).\\nm dòng tiếp theo mỗi dòng chứa ba số u, v, c mô tả cung có hướng từ u đến v với sức chứa c (1 <= u, v <= n, 1 <= c <= 10^9).","outputFormat":"In ra một số nguyên duy nhất là giá trị luồng cực đại.","constraints":["n <= 500, m <= 1000"],"samples":[{"input":"4 5\n1 2 3\n1 3 2\n2 3 1\n2 4 2\n3 4 3","output":"5","explanation":"Luồng cực đại là 5: đường 1->2->4 luồng 2, đường 1->3->4 luồng 2, đường 1->2->3->4 luồng 1."}],"testCases":[{"input":"4 5\n1 2 3\n1 3 2\n2 3 1\n2 4 2\n3 4 3","expected":"5"},{"input":"2 1\n1 2 10","expected":"10"},{"input":"3 2\n1 2 5\n2 3 3","expected":"3"}]},{"id":"p31","name":"Tổng hai số nguyên A + B","category":"Căn bản & Nhập xuất","difficulty":"Cơ bản","description":"Cho hai số nguyên $A$ và $B$. Hãy tính và in ra giá trị $A + B$.\n\nLưu ý: Giá trị của $A$ và $B$ có thể lên tới $10^{18}$, vì vậy hãy sử dụng kiểu dữ liệu 64-bit `long long` trong C++ để tránh bị tràn số.","inputFormat":"Gồm một dòng duy nhất chứa hai số nguyên $A$ và $B$ cách nhau bởi dấu cách.","outputFormat":"In ra một số nguyên duy nhất là giá trị $A + B$.","constraints":["-10^{18} \\le A, B \\le 10^{18}"],"samples":[{"input":"3 5","output":"8","explanation":"3 + 5 = 8."},{"input":"1000000000000 2000000000000","output":"3000000000000","explanation":"Tổng hai số 64-bit."}],"testCases":[{"input":"3 5","expected":"8"},{"input":"-10 25","expected":"15"},{"input":"1000000000000 2000000000000","expected":"3000000000000"},{"input":"-500000000000 -300000000000","expected":"-800000000000"}]},{"id":"p32","name":"Chu vi và diện tích hình chữ nhật","category":"Căn bản & Nhập xuất","difficulty":"Cơ bản","description":"Cho chiều dài $A$ và chiều rộng $B$ của một hình chữ nhật. Hãy tính chu vi $P$ và diện tích $S$ của hình chữ nhật đó.\n\nCông thức:\n- Chu vi: $P = 2 \\times (A + B)$\n- Diện tích: $S = A \\times B$","inputFormat":"Gồm một dòng chứa hai số nguyên dương $A$ và $B$.","outputFormat":"In ra hai số nguyên $P$ và $S$ cách nhau bởi dấu cách.","constraints":["1 \\le A, B \\le 10^8"],"samples":[{"input":"4 5","output":"18 20","explanation":"P = 2*(4+5) = 18, S = 4*5 = 20."}],"testCases":[{"input":"4 5","expected":"18 20"},{"input":"10 10","expected":"40 100"},{"input":"100000000 100000000","expected":"400000000 10000000000000000"}]},{"id":"p33","name":"Chuyển đổi nhiệt độ Celsius sang Fahrenheit","category":"Căn bản & Nhập xuất","difficulty":"Cơ bản","description":"Cho nhiệt độ đo bằng độ Celsius ($C$). Hãy chuyển đổi sang nhiệt độ Fahrenheit ($F$) theo công thức:\n\n$$F = C \\times 1.8 + 32$$\n\nIn ra kết quả với đúng 2 chữ số sau dấu phẩy.","inputFormat":"Một số thực $C$ là nhiệt độ theo độ Celsius.","outputFormat":"In ra nhiệt độ theo độ Fahrenheit với đúng 2 chữ số thập phân.","constraints":["-100.0 \\le C \\le 1000.0"],"samples":[{"input":"25","output":"77.00","explanation":"25 * 1.8 + 32 = 77.00."},{"input":"0","output":"32.00","explanation":"0 * 1.8 + 32 = 32.00."}],"testCases":[{"input":"25","expected":"77.00"},{"input":"0","expected":"32.00"},{"input":"-40","expected":"-40.00"},{"input":"37.5","expected":"99.50"}]},{"id":"p34","name":"Quy đổi giây sang Giờ, Phút, Giây","category":"Căn bản & Nhập xuất","difficulty":"Cơ bản","description":"Cho một khoảng thời gian $T$ tính bằng giây. Hãy quy đổi khoảng thời gian này thành số Giờ, số Phút và số Giây tương ứng.","inputFormat":"Một số nguyên không âm $T$.","outputFormat":"In ra ba số nguyên $H, M, S$ cách nhau bởi dấu cách.","constraints":["0 \\le T \\le 10^9"],"samples":[{"input":"3665","output":"1 1 5","explanation":"3665 giây = 1 giờ, 1 phút, 5 giây."},{"input":"7200","output":"2 0 0","explanation":"7200 giây = 2 giờ tròn."}],"testCases":[{"input":"3665","expected":"1 1 5"},{"input":"7200","expected":"2 0 0"},{"input":"59","expected":"0 0 59"},{"input":"86400","expected":"24 0 0"}]},{"id":"p35","name":"Chia kẹo cho học sinh","category":"Căn bản & Nhập xuất","difficulty":"Cơ bản","description":"Thầy giáo có $K$ cái kẹo cần chia đều cho $N$ bạn học sinh sao cho bạn nào cũng nhận được số kẹo như nhau và nhiều nhất có thể. Số kẹo thừa ra sẽ được giữ lại.\n\nHãy tìm số kẹo mỗi bạn học sinh nhận được và số kẹo còn dư lại.","inputFormat":"Gồm một dòng chứa hai số nguyên dương $K$ và $N$.","outputFormat":"In ra hai số nguyên: số kẹo mỗi bạn nhận được và số kẹo dư.","constraints":["1 \\le K \\le 10^9","1 \\le N \\le 10^6"],"samples":[{"input":"17 5","output":"3 2","explanation":"17 / 5 = 3 dư 2."}],"testCases":[{"input":"17 5","expected":"3 2"},{"input":"20 4","expected":"5 0"},{"input":"3 10","expected":"0 3"}]},{"id":"p36","name":"Kiểm tra năm nhuận (Leap Year)","category":"Cấu trúc rẽ nhánh","difficulty":"Cơ bản","description":"Theo lịch Gregory, một năm $Y$ là năm nhuận nếu thỏa mãn điều kiện:\n- Chia hết cho 400, HOẶC\n- Chia hết cho 4 VÀ không chia hết cho 100.\n\nNhập năm $Y$, in ra `YES` nếu là năm nhuận, ngược lại in `NO`.","inputFormat":"Một số nguyên dương $Y$ biểu thị năm.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le Y \\le 10^6"],"samples":[{"input":"2024","output":"YES","explanation":"2024 chia hết cho 4 và không chia hết cho 100."},{"input":"1900","output":"NO","explanation":"1900 chia hết cho 100 nhưng không chia hết cho 400."},{"input":"2000","output":"YES","explanation":"2000 chia hết cho 400."}],"testCases":[{"input":"2024","expected":"YES"},{"input":"1900","expected":"NO"},{"input":"2000","expected":"YES"},{"input":"2023","expected":"NO"}]},{"id":"p37","name":"Tìm số lớn nhất trong ba số","category":"Cấu trúc rẽ nhánh","difficulty":"Cơ bản","description":"Cho ba số nguyên $a, b, c$. Hãy tìm và in ra số có giá trị lớn nhất trong ba số đó.","inputFormat":"Một dòng chứa ba số nguyên $a, b, c$ cách nhau bởi dấu cách.","outputFormat":"In ra số nguyên lớn nhất.","constraints":["-10^9 \\le a, b, c \\le 10^9"],"samples":[{"input":"3 9 5","output":"9","explanation":"9 là số lớn nhất trong 3 số."}],"testCases":[{"input":"3 9 5","expected":"9"},{"input":"-10 -5 -20","expected":"-5"},{"input":"7 7 7","expected":"7"},{"input":"100 50 100","expected":"100"}]},{"id":"p38","name":"Phân loại tam giác","category":"Cấu trúc rẽ nhánh","difficulty":"Cơ bản","description":"Cho ba số nguyên dương $a, b, c$ là độ dài ba cạnh. Hãy phân loại tam giác:\n- Nếu không tạo thành tam giác (tổng 2 cạnh bất kỳ nhỏ hơn hoặc bằng cạnh còn lại): in `INVALID`.\n- Nếu là tam giác đều (3 cạnh bằng nhau): in `EQUILATERAL`.\n- Nếu là tam giác vuông ($a^2 + b^2 = c^2$ hoặc tương tự): in `RIGHT`.\n- Nếu là tam giác cân (2 cạnh bằng nhau): in `ISOSCELES`.\n- Ngược lại: in `SCALENE` (tam giác thường).","inputFormat":"Gồm ba số nguyên dương $a, b, c$.","outputFormat":"In ra chuỗi kết quả tương ứng.","constraints":["1 \\le a, b, c \\le 10^4"],"samples":[{"input":"3 4 5","output":"RIGHT","explanation":"3^2 + 4^2 = 5^2 nên là tam giác vuông."},{"input":"5 5 5","output":"EQUILATERAL","explanation":"3 cạnh bằng nhau."},{"input":"1 2 5","output":"INVALID","explanation":"1 + 2 < 5 không tạo thành tam giác."}],"testCases":[{"input":"3 4 5","expected":"RIGHT"},{"input":"5 5 5","expected":"EQUILATERAL"},{"input":"1 2 5","expected":"INVALID"},{"input":"4 4 6","expected":"ISOSCELES"},{"input":"4 5 6","expected":"SCALENE"}]},{"id":"p39","name":"Tính cước taxi bậc thang","category":"Cấu trúc rẽ nhánh","difficulty":"Cơ bản","description":"Cước taxi được tính theo số km di chuyển $d$ (số nguyên dương) như sau:\n- 1 km đầu tiên: 15.000 VNĐ.\n- Từ km thứ 2 đến km thứ 5: 13.500 VNĐ mỗi km.\n- Từ km thứ 6 trở đi: 11.000 VNĐ mỗi km.\n- Đặc biệt: Nếu đi trên 120 km (nghĩa là $d > 120$), hành khách được giảm giá 10% trên TỔNG hóa đơn.\n\nHãy tính số tiền khách phải trả (làm tròn số nguyên).","inputFormat":"Một số nguyên dương $d$ là quãng đường đi được tính bằng km.","outputFormat":"In ra số tiền nguyên cần thanh toán.","constraints":["1 \\le d \\le 1000"],"samples":[{"input":"1","output":"15000","explanation":"1 km giá 15.000."},{"input":"3","output":"42000","explanation":"15000 + 2 * 13500 = 42000."}],"testCases":[{"input":"1","expected":"15000"},{"input":"3","expected":"42000"},{"input":"10","expected":"124000"},{"input":"150","expected":"1497600"}]},{"id":"p40","name":"Giải phương trình bậc nhất ax + b = 0","category":"Cấu trúc rẽ nhánh","difficulty":"Cơ bản","description":"Cho phương trình bậc nhất $ax + b = 0$.\n- Nếu phương trình có vô số nghiệm: in `INF`.\n- Nếu phương trình vô nghiệm: in `NO`.\n- Nếu phương trình có một nghiệm duy nhất: in nghiệm với đúng 2 chữ số thập phân.","inputFormat":"Gồm hai số nguyên $a$ và $b$ trên một dòng.","outputFormat":"In ra chuỗi kết quả hoặc số thực theo yêu cầu.","constraints":["-1000 \\le a, b \\le 1000"],"samples":[{"input":"2 -4","output":"2.00","explanation":"2x - 4 = 0 => x = 2.00."},{"input":"0 5","output":"NO","explanation":"0x + 5 = 0 vô nghiệm."},{"input":"0 0","output":"INF","explanation":"0x + 0 = 0 vô số nghiệm."}],"testCases":[{"input":"2 -4","expected":"2.00"},{"input":"0 5","expected":"NO"},{"input":"0 0","expected":"INF"},{"input":"3 1","expected":"-0.33"}]},{"id":"p41","name":"Tính tổng dãy số 1 đến N","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Tính tổng $S = 1 + 2 + 3 + \\dots + N$.\n\nLưu ý: $N$ có thể lên tới $10^9$. Sử dụng công thức đại số Gauss $S = \\frac{N \\times (N + 1)}{2}$ thay vì vòng lặp for để đạt độ phức tạp $O(1)$ và tránh lỗi quá thời gian (TLE).","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra tổng $S$.","constraints":["1 \\le N \\le 10^9"],"samples":[{"input":"5","output":"15","explanation":"1 + 2 + 3 + 4 + 5 = 15."},{"input":"100","output":"5050","explanation":"Tổng từ 1 đến 100."}],"testCases":[{"input":"5","expected":"15"},{"input":"100","expected":"5050"},{"input":"1000000000","expected":"500000000500000000"}]},{"id":"p42","name":"Tính giai thừa N!","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Tính giai thừa $N! = 1 \\times 2 \\times 3 \\times \\dots \\times N$. Quy ước $0! = 1$.\n\nVới $N \\le 20$, kết quả vừa vặn trong kiểu `long long`.","inputFormat":"Một số nguyên không âm $N$.","outputFormat":"In ra giá trị $N!$.","constraints":["0 \\le N \\le 20"],"samples":[{"input":"5","output":"120","explanation":"5! = 120."},{"input":"0","output":"1","explanation":"0! = 1."}],"testCases":[{"input":"5","expected":"120"},{"input":"0","expected":"1"},{"input":"10","expected":"3628800"},{"input":"20","expected":"2432902008176640000"}]},{"id":"p43","name":"Đếm số ước nguyên dương của N","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Cho một số nguyên dương $N$. Hãy đếm số lượng các ước số nguyên dương của $N$.\n\nVí dụ: Với $N = 12$, các ước của 12 là {1, 2, 3, 4, 6, 12}, có tất cả 6 ước.","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra số lượng ước của $N$.","constraints":["1 \\le N \\le 10^9"],"samples":[{"input":"12","output":"6","explanation":"Các ước là 1, 2, 3, 4, 6, 12."},{"input":"16","output":"5","explanation":"Các ước là 1, 2, 4, 8, 16."}],"testCases":[{"input":"12","expected":"6"},{"input":"16","expected":"5"},{"input":"1","expected":"1"},{"input":"1000000000","expected":"100"}]},{"id":"p44","name":"Tổng và đếm chữ số của số nguyên","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Cho một số nguyên không âm $N$. Hãy đếm số lượng chữ số và tính tổng các chữ số của $N$.\n\nVí dụ: $N = 12345$ có 5 chữ số và tổng các chữ số là $1+2+3+4+5 = 15$.","inputFormat":"Một số nguyên $N$ ($N \\ge 0$).","outputFormat":"In ra hai số nguyên: Số lượng chữ số và Tổng các chữ số cách nhau bởi dấu cách.","constraints":["0 \\le N \\le 10^{18}"],"samples":[{"input":"12345","output":"5 15","explanation":"5 chữ số, tổng 15."},{"input":"0","output":"1 0","explanation":"Số 0 có 1 chữ số và tổng 0."}],"testCases":[{"input":"12345","expected":"5 15"},{"input":"0","expected":"1 0"},{"input":"9999","expected":"4 36"},{"input":"1000000000000000000","expected":"19 1"}]},{"id":"p45","name":"Đảo ngược số nguyên (Reverse Integer)","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Cho một số nguyên dương $N$. Hãy đảo ngược thứ tự các chữ số của $N$ và in ra số thu được (bỏ qua các chữ số 0 vô nghĩa ở đầu).\n\nVí dụ: $1234 \\to 4321$, $1200 \\to 21$.","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra số nguyên sau khi đảo ngược.","constraints":["1 \\le N \\le 10^{18}"],"samples":[{"input":"1234","output":"4321","explanation":"Đảo ngược 1234 thành 4321."},{"input":"1200","output":"21","explanation":"Đảo ngược 1200 thành 0021 = 21."}],"testCases":[{"input":"1234","expected":"4321"},{"input":"1200","expected":"21"},{"input":"7","expected":"7"},{"input":"900000000000000001","expected":"100000000000000009"}]},{"id":"p46","name":"Kiểm tra số nguyên tố","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Số nguyên tố là số nguyên lớn hơn 1 và chỉ có đúng hai ước là 1 và chính nó.\n\nCho số nguyên dương $N$. Kiểm tra $N$ có phải là số nguyên tố hay không. In `YES` nếu đúng, ngược lại in `NO`.","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le N \\le 10^{12}"],"samples":[{"input":"17","output":"YES","explanation":"17 là số nguyên tố."},{"input":"4","output":"NO","explanation":"4 chia hết cho 2."},{"input":"1","output":"NO","explanation":"1 không phải số nguyên tố."}],"testCases":[{"input":"17","expected":"YES"},{"input":"4","expected":"NO"},{"input":"1","expected":"NO"},{"input":"999999999989","expected":"YES"}]},{"id":"p47","name":"In bảng cửu chương của số K","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Cho một số nguyên $K$ ($1 \\le K \\le 9$). Hãy in ra bảng nhân (bảng cửu chương) của $K$ từ 1 đến 10 theo định dạng:\n`K x 1 = ...`\n`K x 2 = ...`\n...\n`K x 10 = ...`","inputFormat":"Một số nguyên $K$.","outputFormat":"Gồm 10 dòng, mỗi dòng in theo định dạng `K x i = result`.","constraints":["1 \\le K \\le 9"],"samples":[{"input":"3","output":"3 x 1 = 3\n3 x 2 = 6\n3 x 3 = 9\n3 x 4 = 12\n3 x 5 = 15\n3 x 6 = 18\n3 x 7 = 21\n3 x 8 = 24\n3 x 9 = 27\n3 x 10 = 30","explanation":"Bảng nhân 3."}],"testCases":[{"input":"3","expected":"3 x 1 = 3\n3 x 2 = 6\n3 x 3 = 9\n3 x 4 = 12\n3 x 5 = 15\n3 x 6 = 18\n3 x 7 = 21\n3 x 8 = 24\n3 x 9 = 27\n3 x 10 = 30"},{"input":"7","expected":"7 x 1 = 7\n7 x 2 = 14\n7 x 3 = 21\n7 x 4 = 28\n7 x 5 = 35\n7 x 6 = 42\n7 x 7 = 49\n7 x 8 = 56\n7 x 9 = 63\n7 x 10 = 70"}]},{"id":"p48","name":"Số Fibonacci thứ N modulo 10^9+7","category":"Vòng lặp & Dãy số","difficulty":"Cơ bản","description":"Dãy số Fibonacci được định nghĩa:\n$F_0 = 0, F_1 = 1$\n$F_n = (F_{n-1} + F_{n-2}) \\pmod{10^9+7}$ với $n \\ge 2$.\n\nCho $N$. Hãy tính giá trị của số $F_N$.","inputFormat":"Một số nguyên $N$ ($0 \\le N \\le 10^6$).","outputFormat":"In ra $F_N \\pmod{10^9+7}$.","constraints":["0 \\le N \\le 10^6"],"samples":[{"input":"7","output":"13","explanation":"Dãy: 0, 1, 1, 2, 3, 5, 8, 13."},{"input":"10","output":"55","explanation":"F(10) = 55."}],"testCases":[{"input":"7","expected":"13"},{"input":"10","expected":"55"},{"input":"0","expected":"0"},{"input":"100","expected":"687995182"}]},{"id":"p49","name":"Tìm Min và Max trong mảng","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Cho mảng gồm $N$ số nguyên. Hãy tìm phần tử nhỏ nhất và phần tử lớn nhất trong mảng đó.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên cách nhau bởi dấu cách.","outputFormat":"In ra hai số: Phần tử nhỏ nhất và phần tử lớn nhất cách nhau bởi dấu cách.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"5\n3 1 9 7 2","output":"1 9","explanation":"Min = 1, Max = 9."}],"testCases":[{"input":"5\n3 1 9 7 2","expected":"1 9"},{"input":"1\n42","expected":"42 42"},{"input":"4\n-10 -50 -5 -20","expected":"-50 -5"}]},{"id":"p50","name":"Đếm số lượng số chẵn và số lẻ","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Cho mảng gồm $N$ số nguyên. Hãy đếm xem có bao nhiêu số chẵn và bao nhiêu số lẻ trong mảng.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra hai số: Số lượng số chẵn và Số lượng số lẻ cách nhau bởi dấu cách.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"6\n2 5 8 11 14 7","output":"3 3","explanation":"Chẵn: 2, 8, 14 (3 số). Lẻ: 5, 11, 7 (3 số)."}],"testCases":[{"input":"6\n2 5 8 11 14 7","expected":"3 3"},{"input":"3\n2 4 6","expected":"3 0"},{"input":"3\n1 3 5","expected":"0 3"}]},{"id":"p51","name":"Đảo ngược mảng 1 chiều","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Cho mảng gồm $N$ phần tử. Hãy đảo ngược thứ tự các phần tử của mảng và in ra màn hình.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra $N$ số sau khi đã đảo ngược trên một dòng cách nhau bởi dấu cách.","constraints":["1 \\le N \\le 10^5"],"samples":[{"input":"4\n1 2 3 4","output":"4 3 2 1","explanation":"Đảo ngược mảng."}],"testCases":[{"input":"4\n1 2 3 4","expected":"4 3 2 1"},{"input":"1\n100","expected":"100"},{"input":"5\n10 20 30 40 50","expected":"50 40 30 20 10"}]},{"id":"p52","name":"Tìm vị trí đầu tiên của giá trị X","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Cho mảng $A$ gồm $N$ số nguyên (đánh số chỉ số từ 1 đến $N$) và một số nguyên $X$.\n\nHãy tìm vị trí (chỉ số 1-indexed) xuất hiện ĐẦU TIÊN của $X$ trong mảng. Nếu $X$ không xuất hiện trong mảng, in `-1`.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $X$. Dòng 2: $N$ số nguyên của mảng $A$.","outputFormat":"In ra vị trí đầu tiên tìm thấy hoặc `-1`.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i, X \\le 10^9"],"samples":[{"input":"5 7\n1 3 7 9 7","output":"3","explanation":"Số 7 xuất hiện đầu tiên tại vị trí thứ 3."},{"input":"4 10\n1 2 3 4","output":"-1","explanation":"Không tìm thấy số 10."}],"testCases":[{"input":"5 7\n1 3 7 9 7","expected":"3"},{"input":"4 10\n1 2 3 4","expected":"-1"},{"input":"1 5\n5","expected":"1"}]},{"id":"p53","name":"Trung bình cộng các số dương trong mảng","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Cho mảng $A$ gồm $N$ số nguyên. Hãy tính giá trị trung bình cộng của tất cả các phần tử $A_i > 0$ trong mảng.\n\nIn ra kết quả với đúng 2 chữ số thập phân. Nếu trong mảng không có số dương nào, in `-1`.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra giá trị trung bình cộng hoặc `-1`.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"4\n-2 4 6 -8","output":"5.00","explanation":"Các số dương là 4 và 6. Trung bình cộng = (4+6)/2 = 5.00."},{"input":"3\n-1 -2 -3","output":"-1","explanation":"Không có số dương nào."}],"testCases":[{"input":"4\n-2 4 6 -8","expected":"5.00"},{"input":"3\n-1 -2 -3","expected":"-1"},{"input":"3\n1 2 4","expected":"2.33"}]},{"id":"p54","name":"Kiểm tra mảng tăng dần nghiêm ngặt","category":"Mảng 1 chiều","difficulty":"Cơ bản","description":"Mảng $A$ gồm $N$ số nguyên được gọi là tăng dần nghiêm ngặt nếu với mọi $i$ từ $0$ đến $N-2$, ta đều có $A_i < A_{i+1}$.\n\nHãy kiểm tra xem mảng có tăng dần nghiêm ngặt không. In `YES` nếu có, ngược lại in `NO`.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le N \\le 10^5"],"samples":[{"input":"4\n1 3 5 8","output":"YES","explanation":"1 < 3 < 5 < 8 thỏa mãn."},{"input":"3\n1 2 2","output":"NO","explanation":"2 không nhỏ hơn 2 nên vi phạm."}],"testCases":[{"input":"4\n1 3 5 8","expected":"YES"},{"input":"3\n1 2 2","expected":"NO"},{"input":"1\n100","expected":"YES"},{"input":"5\n5 4 3 2 1","expected":"NO"}]},{"id":"p55","name":"Xóa phần tử trùng lặp trong mảng đã sắp xếp","category":"Mảng 1 chiều","difficulty":"Trung bình","description":"Cho một mảng $A$ gồm $N$ số nguyên ĐÃ ĐƯỢC SẮP XẾP tăng dần. Hãy loại bỏ tất cả các phần tử bị trùng lặp và in ra các phần tử duy nhất theo thứ tự tăng dần.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên đã sắp xếp.","outputFormat":"In ra danh sách các số phân biệt trên một dòng cách nhau bởi dấu cách.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"6\n1 1 2 3 3 5","output":"1 2 3 5","explanation":"Các phần tử duy nhất: 1, 2, 3, 5."}],"testCases":[{"input":"6\n1 1 2 3 3 5","expected":"1 2 3 5"},{"input":"4\n7 7 7 7","expected":"7"},{"input":"3\n1 2 3","expected":"1 2 3"}]},{"id":"p56","name":"Dịch vòng phải mảng K vị trí","category":"Mảng 1 chiều","difficulty":"Trung bình","description":"Cho một mảng $A$ gồm $N$ số nguyên và một số nguyên dương $K$. Hãy dịch chuyển xoay vòng sang phải các phần tử của mảng đúng $K$ lần.\n\nVí dụ: Mảng `[1, 2, 3, 4, 5]` dịch phải $K = 2$ lần sẽ trở thành `[4, 5, 1, 2, 3]`.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $K$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra mảng sau khi dịch vòng phải.","constraints":["1 \\le N \\le 10^5","1 \\le K \\le 10^9"],"samples":[{"input":"5 2\n1 2 3 4 5","output":"4 5 1 2 3","explanation":"Dịch phải 2 vị trí."}],"testCases":[{"input":"5 2\n1 2 3 4 5","expected":"4 5 1 2 3"},{"input":"4 4\n10 20 30 40","expected":"10 20 30 40"},{"input":"3 10\n1 2 3","expected":"3 1 2"}]},{"id":"p57","name":"Tìm phần tử lớn thứ nhì trong mảng","category":"Mảng 1 chiều","difficulty":"Trung bình","description":"Cho mảng $A$ gồm $N$ số nguyên. Hãy tìm giá trị lớn thứ nhì nghiêm ngặt trong mảng (nghĩa là giá trị lớn nhất trong số các phần tử nhỏ hơn phần tử lớn nhất của mảng).\n\nNếu trong mảng tất cả các phần tử đều bằng nhau (không tồn tại phần tử lớn thứ nhì), hãy in `-1`.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra giá trị lớn thứ nhì hoặc `-1`.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"5\n5 3 5 2 4","output":"4","explanation":"Giá trị lớn nhất là 5, giá trị lớn thứ nhì là 4."},{"input":"3\n7 7 7","output":"-1","explanation":"Tất cả các số bằng nhau."}],"testCases":[{"input":"5\n5 3 5 2 4","expected":"4"},{"input":"3\n7 7 7","expected":"-1"},{"input":"2\n1 2","expected":"1"},{"input":"4\n-10 -5 -20 -1","expected":"-5"}]},{"id":"p58","name":"Đếm số cặp nghịch thế trong mảng","category":"Mảng 1 chiều","difficulty":"Trung bình","description":"Cho mảng $A$ gồm $N$ số nguyên. Một cặp chỉ số $(i, j)$ được gọi là một cặp nghịch thế nếu thỏa mãn:\n- $0 \\le i < j < N$\n- $A_i > A_j$\n\nHãy đếm tổng số cặp nghịch thế trong mảng.","inputFormat":"Dòng 1: Số nguyên $N$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra một số nguyên là số lượng cặp nghịch thế.","constraints":["1 \\le N \\le 2000","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"4\n3 1 2 4","output":"2","explanation":"Các cặp nghịch thế là (3, 1) và (3, 2)."}],"testCases":[{"input":"4\n3 1 2 4","expected":"2"},{"input":"5\n5 4 3 2 1","expected":"10"},{"input":"4\n1 2 3 4","expected":"0"}]},{"id":"p59","name":"Tổng đường chéo chính ma trận vuông","category":"Mảng 2 chiều","difficulty":"Cơ bản","description":"Cho một ma trận vuông $A$ kích thước $N \\times N$. Hãy tính tổng các phần tử nằm trên đường chéo chính của ma trận (các phần tử có chỉ số hàng bằng chỉ số cột: $A_{0,0} + A_{1,1} + \\dots + A_{N-1, N-1}$).","inputFormat":"Dòng 1: Số nguyên dương $N$. $N$ dòng tiếp theo, mỗi dòng chứa $N$ số nguyên.","outputFormat":"In ra một số nguyên là tổng đường chéo chính.","constraints":["1 \\le N \\le 500","-10^9 \\le A_{i,j} \\le 10^9"],"samples":[{"input":"3\n1 2 3\n4 5 6\n7 8 9","output":"15","explanation":"1 + 5 + 9 = 15."}],"testCases":[{"input":"3\n1 2 3\n4 5 6\n7 8 9","expected":"15"},{"input":"2\n-5 10\n20 -3","expected":"-8"},{"input":"1\n100","expected":"100"}]},{"id":"p60","name":"Phần tử lớn nhất trong từng hàng ma trận","category":"Mảng 2 chiều","difficulty":"Cơ bản","description":"Cho ma trận $A$ kích thước $N \\times M$. Hãy tìm và in ra phần tử lớn nhất của mỗi hàng.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $M$. $N$ dòng tiếp theo, mỗi dòng gồm $M$ số nguyên.","outputFormat":"Gồm $N$ dòng, dòng thứ $i$ in ra giá trị lớn nhất của hàng thứ $i$.","constraints":["1 \\le N, M \\le 500","-10^9 \\le A_{i,j} \\le 10^9"],"samples":[{"input":"2 3\n1 5 3\n9 2 4","output":"5\n9","explanation":"Hàng 1 max là 5, hàng 2 max là 9."}],"testCases":[{"input":"2 3\n1 5 3\n9 2 4","expected":"5\n9"},{"input":"3 1\n10\n-5\n20","expected":"10\n-5\n20"},{"input":"1 4\n-1 -9 -3 -2","expected":"-1"}]},{"id":"p61","name":"Chuyển vị ma trận (Transpose Matrix)","category":"Mảng 2 chiều","difficulty":"Trung bình","description":"Cho ma trận $A$ kích thước $N$ hàng và $M$ cột. Ma trận chuyển vị $B$ kích thước $M$ hàng và $N$ cột được tạo bằng cách biến hàng của $A$ thành cột của $B$ ($B_{j, i} = A_{i, j}$).\n\nHãy in ra ma trận chuyển vị $B$.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $M$. $N$ dòng tiếp theo, mỗi dòng gồm $M$ số nguyên.","outputFormat":"In ra ma trận chuyển vị gồm $M$ dòng, mỗi dòng $N$ số nguyên.","constraints":["1 \\le N, M \\le 300"],"samples":[{"input":"2 3\n1 2 3\n4 5 6","output":"1 4\n2 5\n3 6","explanation":"Ma trận 2x3 chuyển vị thành 3x2."}],"testCases":[{"input":"2 3\n1 2 3\n4 5 6","expected":"1 4\n2 5\n3 6"},{"input":"2 2\n1 2\n3 4","expected":"1 3\n2 4"},{"input":"1 3\n7 8 9","expected":"7\n8\n9"}]},{"id":"p62","name":"Tính tổng các phần tử trên biên ma trận","category":"Mảng 2 chiều","difficulty":"Trung bình","description":"Cho ma trận $A$ kích thước $N \\times M$. Các phần tử biên là các phần tử nằm trên hàng đầu tiên ($i = 0$), hàng cuối cùng ($i = N-1$), cột đầu tiên ($j = 0$), hoặc cột cuối cùng ($j = M-1$).\n\nHãy tính tổng tất cả các phần tử biên (mỗi phần tử chỉ được tính đúng 1 lần).","inputFormat":"Dòng 1: Hai số nguyên $N$ và $M$. $N$ dòng tiếp theo là các phần tử của ma trận.","outputFormat":"In ra một số nguyên là tổng các phần tử biên.","constraints":["1 \\le N, M \\le 500"],"samples":[{"input":"3 3\n1 2 3\n4 5 6\n7 8 9","output":"40","explanation":"Tổng biên = 1+2+3+4+6+7+8+9 = 40 (bỏ số 5 ở giữa)."}],"testCases":[{"input":"3 3\n1 2 3\n4 5 6\n7 8 9","expected":"40"},{"input":"2 2\n1 1\n1 1","expected":"4"},{"input":"1 4\n5 5 5 5","expected":"20"}]},{"id":"p63","name":"Đếm điểm cực đại địa phương trong ma trận","category":"Mảng 2 chiều","difficulty":"Trung bình","description":"Cho ma trận $A$ kích thước $N \\times M$. Một ô $(i, j)$ được gọi là điểm cực đại địa phương nếu giá trị của nó LỚN HƠN NGHIÊM NGẶT tất cả các ô chung cạnh với nó (trên, dưới, trái, phải nằm trong bảng).\n\nHãy đếm số lượng điểm cực đại địa phương trong ma trận.","inputFormat":"Dòng 1: Hai số $N, M$. $N$ dòng tiếp theo là ma trận $A$.","outputFormat":"In ra số lượng điểm cực đại.","constraints":["1 \\le N, M \\le 300","-10^9 \\le A_{i,j} \\le 10^9"],"samples":[{"input":"3 3\n1 2 1\n2 9 2\n1 2 1","output":"1","explanation":"Chỉ có ô ở giữa giá trị 9 là cực đại địa phương."}],"testCases":[{"input":"3 3\n1 2 1\n2 9 2\n1 2 1","expected":"1"},{"input":"2 2\n5 5\n5 5","expected":"0"},{"input":"1 3\n1 4 2","expected":"1"}]},{"id":"p64","name":"Kiểm tra chuỗi đối xứng (Palindrome)","category":"Chuỗi ký tự (String)","difficulty":"Cơ bản","description":"Một chuỗi ký tự được gọi là chuỗi đối xứng (Palindrome) nếu đọc từ trái sang phải hay từ phải sang trái đều thu được chuỗi giống nhau.\n\nCho chuỗi $S$. In `YES` nếu là chuỗi đối xứng, ngược lại in `NO`.","inputFormat":"Một chuỗi ký tự $S$ gồm các chữ cái in thường không có khoảng trắng.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"radar","output":"YES","explanation":"radar đối xứng."},{"input":"hello","output":"NO","explanation":"hello không đối xứng."}],"testCases":[{"input":"radar","expected":"YES"},{"input":"hello","expected":"NO"},{"input":"a","expected":"YES"},{"input":"abccba","expected":"YES"}]},{"id":"p65","name":"Đếm số nguyên âm trong chuỗi","category":"Chuỗi ký tự (String)","difficulty":"Cơ bản","description":"Cho một chuỗi ký tự $S$ (có thể chứa cả chữ hoa và chữ thường). Hãy đếm số lượng nguyên âm tiếng Anh (`u, e, o, a, i` không phân biệt chữ hoa hay thường) có trong chuỗi.","inputFormat":"Một chuỗi ký tự $S$ (đọc cả dòng).","outputFormat":"In ra số lượng nguyên âm.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"Hello World","output":"3","explanation":"Các nguyên âm: e, o, o (tổng cộng 3)."}],"testCases":[{"input":"Hello World","expected":"3"},{"input":"AEIOU","expected":"5"},{"input":"bcdfgh","expected":"0"}]},{"id":"p66","name":"Chuyển đổi chuỗi sang in hoa","category":"Chuỗi ký tự (String)","difficulty":"Cơ bản","description":"Cho một chuỗi ký tự $S$. Hãy chuyển tất cả các chữ cái thường trong $S$ thành chữ in hoa và in chuỗi kết quả ra màn hình.","inputFormat":"Một dòng chứa chuỗi ký tự $S$.","outputFormat":"In ra chuỗi sau khi đã in hoa.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"Lap Trinh C++","output":"LAP TRINH C++","explanation":"Chuyển đổi các chữ cái thường thành chữ hoa."}],"testCases":[{"input":"Lap Trinh C++","expected":"LAP TRINH C++"},{"input":"hello world","expected":"HELLO WORLD"},{"input":"123 abc!?","expected":"123 ABC!?"}]},{"id":"p67","name":"Đếm số lượng từ trong một câu","category":"Chuỗi ký tự (String)","difficulty":"Cơ bản","description":"Cho một câu văn $S$ gồm nhiều từ phân tách nhau bởi một hoặc nhiều dấu khoảng trắng. Hãy đếm xem câu đó có bao nhiêu từ.","inputFormat":"Một dòng chứa câu văn $S$.","outputFormat":"In ra số lượng từ.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"  Lap trinh   C++  rat   vui ","output":"5","explanation":"5 từ: Lap, trinh, C++, rat, vui."}],"testCases":[{"input":"  Lap trinh   C++  rat   vui ","expected":"5"},{"input":"OneWord","expected":"1"},{"input":"   ","expected":"0"},{"input":"A B C D E F","expected":"6"}]},{"id":"p68","name":"Nén chuỗi Run-Length Encoding","category":"Chuỗi ký tự (String)","difficulty":"Trung bình","description":"Nén chuỗi ký tự bằng phương pháp Run-Length Encoding: Gom các ký tự liên tiếp giống nhau thành dạng `<ký tự><số lần lặp>`.\n\nVí dụ: `aaabbc` $\\to$ `a3b2c1`, `wwww` $\\to$ `w4`.","inputFormat":"Một chuỗi ký tự $S$ gồm các chữ cái in thường không có khoảng trắng.","outputFormat":"In ra chuỗi sau khi nén.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"aaabbc","output":"a3b2c1","explanation":"3 chữ a, 2 chữ b, 1 chữ c."},{"input":"wwww","output":"w4","explanation":"4 chữ w."}],"testCases":[{"input":"aaabbc","expected":"a3b2c1"},{"input":"wwww","expected":"w4"},{"input":"abc","expected":"a1b1c1"}]},{"id":"p69","name":"Kiểm tra hai chuỗi đảo chữ (Anagram)","category":"Chuỗi ký tự (String)","difficulty":"Trung bình","description":"Hai chuỗi được gọi là đảo chữ (Anagram) của nhau nếu ta có thể sắp xếp lại các ký tự của chuỗi thứ nhất để tạo thành chuỗi thứ hai (nghĩa là chúng có cùng độ dài và mỗi ký tự xuất hiện với tần suất như nhau).\n\nCho hai chuỗi $S$ và $T$. In `YES` nếu chúng là Anagram, ngược lại in `NO`.","inputFormat":"Gồm hai chuỗi $S$ và $T$ cách nhau bởi dấu cách.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le |S|, |T| \\le 10^5"],"samples":[{"input":"listen silent","output":"YES","explanation":"listen và silent chứa đúng các ký tự e, i, l, n, s, t."},{"input":"rat car","output":"NO","explanation":"Khác ký tự t và c."}],"testCases":[{"input":"listen silent","expected":"YES"},{"input":"rat car","expected":"NO"},{"input":"anagram nagaram","expected":"YES"}]},{"id":"p70","name":"Độ dài chuỗi con không lặp ký tự dài nhất","category":"Chuỗi ký tự (String)","difficulty":"Trung bình","description":"Cho một chuỗi ký tự $S$. Hãy tìm độ dài của chuỗi con liên tiếp dài nhất mà trong đó KHÔNG có bất kỳ ký tự nào bị lặp lại.\n\nVí dụ: Với chuỗi `abcabcbb`, chuỗi con không lặp dài nhất là `abc` với độ dài là 3.","inputFormat":"Một chuỗi ký tự $S$.","outputFormat":"In ra một số nguyên là độ dài lớn nhất.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"abcabcbb","output":"3","explanation":"Chuỗi abc có độ dài 3."},{"input":"bbbbb","output":"1","explanation":"Chuỗi b có độ dài 1."}],"testCases":[{"input":"abcabcbb","expected":"3"},{"input":"bbbbb","expected":"1"},{"input":"pwwkew","expected":"3"}]},{"id":"p71","name":"Tìm kiếm nhị phân: Vị trí đầu tiên >= X","category":"Tìm kiếm & Sắp xếp","difficulty":"Trung bình","description":"Cho một mảng $A$ gồm $N$ số nguyên ĐÃ ĐƯỢC SẮP XẾP tăng dần (đánh số từ 1 đến $N$) và một giá trị $X$.\n\nHãy tìm chỉ số 1-indexed của phần tử ĐẦU TIÊN trong mảng có giá trị $\\ge X$ (tương đương hàm `lower_bound`). Nếu mọi phần tử đều $< X$, in `-1`.","inputFormat":"Dòng 1: Hai số $N$ và $X$. Dòng 2: $N$ số nguyên đã sắp xếp.","outputFormat":"In ra chỉ số 1-indexed tìm được hoặc `-1`.","constraints":["1 \\le N \\le 10^5","-10^9 \\le A_i, X \\le 10^9"],"samples":[{"input":"5 4\n1 2 4 4 6","output":"3","explanation":"Phần tử đầu tiên >= 4 nằm tại vị trí thứ 3 (giá trị 4)."},{"input":"3 10\n1 3 5","output":"-1","explanation":"Mọi số đều nhỏ hơn 10."}],"testCases":[{"input":"5 4\n1 2 4 4 6","expected":"3"},{"input":"3 10\n1 3 5","expected":"-1"},{"input":"4 0\n2 5 7 9","expected":"1"}]},{"id":"p72","name":"Đếm cặp số có hiệu bằng K","category":"Two Pointers & Hash","difficulty":"Trung bình","description":"Cho một mảng gồm $N$ số nguyên dương PHÂN BIỆT và một số nguyên dương $K$. Hãy đếm số lượng cặp chỉ số $(i, j)$ sao cho:\n$$A_j - A_i = K$$\n\nYêu cầu thuật toán đạt độ phức tạp $O(N \\log N)$ hoặc $O(N)$.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $K$. Dòng 2: $N$ số nguyên phân biệt.","outputFormat":"In ra số lượng cặp thỏa mãn.","constraints":["1 \\le N \\le 10^5","1 \\le K \\le 10^9","1 \\le A_i \\le 10^9"],"samples":[{"input":"5 2\n1 3 5 8 10","output":"2","explanation":"Các cặp thỏa mãn là (1, 3) và (3, 5) vì 3 - 1 = 2 và 5 - 3 = 2."}],"testCases":[{"input":"5 2\n1 3 5 8 10","expected":"2"},{"input":"4 1\n1 2 3 4","expected":"3"},{"input":"3 5\n1 2 3","expected":"0"}]},{"id":"p73","name":"Tìm phần tử xuất hiện đúng 1 lần (Single Number)","category":"Bitwise & Mảng","difficulty":"Trung bình","description":"Cho một mảng gồm $N$ số nguyên. Trong mảng này, NGOẠI TRỪ duy nhất một số xuất hiện ĐÚNG 1 LẦN, tất cả các số còn lại đều xuất hiện đúng 2 lần.\n\nHãy tìm số xuất hiện đúng 1 lần đó trong $O(N)$ thời gian và $O(1)$ bộ nhớ phụ.","inputFormat":"Dòng 1: Số nguyên $N$ (luôn là số lẻ). Dòng 2: $N$ số nguyên.","outputFormat":"In ra số xuất hiện duy nhất một lần.","constraints":["1 \\le N \\le 2 \\times 10^5","0 \\le A_i \\le 10^9"],"samples":[{"input":"5\n4 1 2 1 2","output":"4","explanation":"Các số 1 và 2 đều xuất hiện 2 lần, chỉ có số 4 xuất hiện 1 lần."}],"testCases":[{"input":"5\n4 1 2 1 2","expected":"4"},{"input":"3\n9 5 9","expected":"5"},{"input":"1\n999","expected":"999"}]},{"id":"p74","name":"Mảng cộng dồn 1D: Truy vấn tổng đoạn [L, R]","category":"Tiền xử lý & Mảng cộng dồn","difficulty":"Trung bình","description":"Cho mảng $A$ gồm $N$ số nguyên (đánh số 1-indexed) và $Q$ truy vấn. Mỗi truy vấn gồm hai số $(L, R)$. Hãy tính và in ra tổng:\n$$\\sum_{i=L}^R A_i$$\n\nYêu cầu trả lời mỗi truy vấn trong thời gian $O(1)$ bằng kỹ thuật Mảng cộng dồn (Prefix Sum).","inputFormat":"Dòng 1: Hai số $N$ và $Q$. Dòng 2: $N$ số nguyên của mảng $A$. $Q$ dòng tiếp theo, mỗi dòng gồm 2 số $L, R$.","outputFormat":"Gồm $Q$ dòng, mỗi dòng in ra kết quả của một truy vấn.","constraints":["1 \\le N, Q \\le 10^5","1 \\le L \\le R \\le N","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"5 2\n1 2 3 4 5\n1 3\n2 5","output":"6\n14","explanation":"Đoạn [1,3] = 1+2+3 = 6. Đoạn [2,5] = 2+3+4+5 = 14."}],"testCases":[{"input":"5 2\n1 2 3 4 5\n1 3\n2 5","expected":"6\n14"},{"input":"3 1\n10 20 30\n1 3","expected":"60"},{"input":"4 2\n-5 10 -2 7\n1 2\n2 4","expected":"5\n15"}]},{"id":"p75","name":"Chọn công việc không giao nhau nhiều nhất (Interval Scheduling)","category":"Tham lam (Greedy)","difficulty":"Trung bình","description":"Có $N$ công việc cần thực hiện, công việc thứ $i$ bắt đầu tại thời điểm $S_i$ và kết thúc tại thời điểm $E_i$. Bạn chỉ có thể làm một công việc tại một thời điểm (hai công việc được coi là không giao nhau nếu $S_j \\ge E_i$).\n\nHãy tìm số lượng công việc nhiều nhất mà bạn có thể hoàn thành.","inputFormat":"Dòng 1: Số nguyên $N$. $N$ dòng tiếp theo, mỗi dòng gồm 2 số nguyên $S_i, E_i$.","outputFormat":"In ra số lượng công việc tối đa chọn được.","constraints":["1 \\le N \\le 10^5","1 \\le S_i < E_i \\le 10^9"],"samples":[{"input":"3\n1 3\n2 5\n4 7","output":"2","explanation":"Chọn công việc (1, 3) và (4, 7)."}],"testCases":[{"input":"3\n1 3\n2 5\n4 7","expected":"2"},{"input":"4\n1 2\n2 3\n3 4\n4 5","expected":"4"},{"input":"3\n1 10\n2 9\n3 8","expected":"1"}]},{"id":"p76","name":"Đổi tiền với số lượng đồng xu ít nhất (Coin Change Greedy)","category":"Tham lam (Greedy)","difficulty":"Trung bình","description":"Hệ thống tiền tệ gồm các mệnh giá: 500, 200, 100, 50, 20, 10, 5, 2, 1 nghìn đồng. Cần đổi số tiền $N$ nghìn đồng thành các tờ tiền trên sao cho TỔNG SỐ LƯỢNG TỜ TIỀN là ít nhất.\n\nHãy tìm số lượng tờ tiền tối thiểu đó.","inputFormat":"Một số nguyên dương $N$ (đơn vị nghìn đồng).","outputFormat":"In ra số lượng tờ tiền ít nhất cần dùng.","constraints":["1 \\le N \\le 10^{12}"],"samples":[{"input":"789","output":"6","explanation":"789 = 500 + 200 + 50 + 20 + 10 + 5 + 2*2 (tổng 6 tờ)."}],"testCases":[{"input":"789","expected":"7"},{"input":"1000","expected":"2"},{"input":"1","expected":"1"}]},{"id":"p77","name":"Cửa sổ trượt: Tổng lớn nhất đoạn con độ dài đúng bằng K","category":"Cửa sổ trượt (Sliding Window)","difficulty":"Trung bình","description":"Cho mảng $A$ gồm $N$ số nguyên và kích thước cửa sổ $K$ ($K \\le N$). Hãy tìm giá trị TỔNG LỚN NHẤT của một đoạn con gồm ĐÚNG $K$ phần tử liên tiếp trong mảng.\n\nYêu cầu thuật toán đạt độ phức tạp $O(N)$.","inputFormat":"Dòng 1: Hai số nguyên $N$ và $K$. Dòng 2: $N$ số nguyên.","outputFormat":"In ra tổng lớn nhất của đoạn $K$ phần tử liên tiếp.","constraints":["1 \\le K \\le N \\le 10^5","-10^9 \\le A_i \\le 10^9"],"samples":[{"input":"5 3\n1 4 2 10 23","output":"35","explanation":"Đoạn 3 phần tử liên tiếp có tổng lớn nhất là [2, 10, 23] với tổng bằng 35."}],"testCases":[{"input":"5 3\n1 4 2 10 23","expected":"35"},{"input":"4 2\n-1 -2 -3 -4","expected":"-3"},{"input":"3 3\n10 20 30","expected":"60"}]},{"id":"p78","name":"Kiểm tra dãy ngoặc hợp lệ bằng Ngăn xếp Stack","category":"Cấu trúc dữ liệu STL","difficulty":"Trung bình","description":"Cho một chuỗi ký tự chỉ gồm các dấu ngoặc tròn `()`, ngoặc vuông `[]`, ngoặc nhọn `{}`. Một chuỗi ngoặc là hợp lệ nếu mọi dấu ngoặc mở đều được đóng đúng thứ tự và đúng loại ngoặc tương ứng.\n\nIn `YES` nếu hợp lệ, ngược lại in `NO`.","inputFormat":"Một dòng chứa chuỗi ký tự ngoặc $S$.","outputFormat":"In ra `YES` hoặc `NO`.","constraints":["1 \\le |S| \\le 10^5"],"samples":[{"input":"{[()]}","output":"YES","explanation":"Đóng mở chuẩn xác."},{"input":"([)]","output":"NO","explanation":"Sai thứ tự lồng nhau."}],"testCases":[{"input":"{[()]}","expected":"YES"},{"input":"([)]","expected":"NO"},{"input":"((()","expected":"NO"},{"input":"()[]{}","expected":"YES"}]},{"id":"p79","name":"Sàng nguyên tố Eratosthenes: Đếm số nguyên tố <= N","category":"Số học & Toán","difficulty":"Trung bình","description":"Cho số nguyên dương $N$. Hãy đếm số lượng số nguyên tố nằm trong đoạn $[1, N]$.\n\nÁp dụng thuật toán Sàng Eratosthenes với độ phức tạp $O(N \\log \\log N)$ để giải quyết trong thời gian giới hạn 1.0s với $N \\le 10^7$.","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra số lượng số nguyên tố.","constraints":["1 \\le N \\le 10^7"],"samples":[{"input":"10","output":"4","explanation":"Các số nguyên tố <= 10 là 2, 3, 5, 7 (4 số)."},{"input":"100","output":"25","explanation":"Có 25 số nguyên tố <= 100."}],"testCases":[{"input":"10","expected":"4"},{"input":"100","expected":"25"},{"input":"1","expected":"0"},{"input":"1000","expected":"168"}]},{"id":"p80","name":"Quy hoạch động: Bài toán bước nhảy bậc thang (Climbing Stairs)","category":"Quy hoạch động cơ bản","difficulty":"Trung bình","description":"Bạn đang leo một cầu thang gồm $N$ bậc. Mỗi bước bạn có thể bước lên 1 bậc hoặc 2 bậc.\n\nHỏi có tất cả bao nhiêu cách khác nhau để leo lên tới đỉnh bậc $N$? Vì kết quả có thể rất lớn, hãy in ra phần dư khi chia cho $10^9+7$.\n\nQuy ước: Với $N = 1$ có 1 cách, $N = 2$ có 2 cách (1+1 hoặc 2), $N = 3$ có 3 cách (1+1+1, 1+2, 2+1).","inputFormat":"Một số nguyên dương $N$.","outputFormat":"In ra số cách leo bậc thang modulo $10^9+7$.","constraints":["1 \\le N \\le 10^6"],"samples":[{"input":"3","output":"3","explanation":"3 cách: (1+1+1), (1+2), (2+1)."},{"input":"5","output":"8","explanation":"8 cách."}],"testCases":[{"input":"3","expected":"3"},{"input":"5","expected":"8"},{"input":"1","expected":"1"},{"input":"10","expected":"89"}]}];